if ($_SERVER['REQUEST_METHOD']==='POST') {
  $action=$_POST['action']??'';
  if ($action==='save') {
    $id=(int)($_POST['id']??0); $title=trim($_POST['title']??''); $author=trim($_POST['author']??''); $category=trim($_POST['category']??''); $isbn=trim($_POST['isbn']??''); $status=$_POST['status']??'Available';
    if ($title===''||$author===''||$category===''||!in_array($status,['Available','Issued'],true)) $error='Complete all required fields.';
    else {
      $pdo->prepare('INSERT IGNORE INTO book_categories(name) VALUES(?)')->execute([$category]);
      if($id>0){$s=$pdo->prepare('UPDATE books SET title=?,author=?,category=?,isbn=?,status=? WHERE id=?');$s->execute([$title,$author,$category,$isbn,$status,$id]);}
      else {$s=$pdo->prepare('INSERT INTO books(title,author,category,isbn,status) VALUES(?,?,?,?,?)');$s->execute([$title,$author,$category,$isbn,$status]);}
      header('Location: index.php?saved=1'); exit;
    }
  } elseif ($action==='add_category') {
    $name=trim($_POST['category_name']??'');
    if($name!=='') { try {$pdo->prepare('INSERT INTO book_categories(name) VALUES(?)')->execute([$name]); header('Location: index.php?category_added=1'); exit;} catch(PDOException $e){$error='That category already exists.';} }
  } elseif ($action==='delete') { $pdo->prepare('DELETE FROM books WHERE id=?')->execute([(int)($_POST['id']??0)]); header('Location: index.php?deleted=1'); exit; }
  elseif ($action==='toggle') { $pdo->prepare("UPDATE books SET status=IF(status='Available','Issued','Available') WHERE id=?")->execute([(int)($_POST['id']??0)]); header('Location: index.php?updated=1'); exit; }
}
